<script setup lang="ts">
import { computed, onMounted, reactive, ref, watch } from 'vue'
import { EditOutlined, MoreOutlined, PlusOutlined, ReloadOutlined, ThunderboltOutlined } from '@ant-design/icons-vue'
import { message, Modal } from 'ant-design-vue'
import { monitoredUsersApi } from '@/services/api'; import { getErrorMessage } from '@/services/http'; import type { CreateMonitoredUserPayload, MonitoredUser, UpdateMonitoredUserPayload } from '@/types'; import { formatDateTime, formatInterval } from '@/utils/format'; import PageHeader from '@/components/PageHeader.vue'; import StatusPill from '@/components/StatusPill.vue'; import MetricCard from '@/components/MetricCard.vue'
const items = ref<MonitoredUser[]>([]); const total = ref(0); const loading = ref(false); const editorOpen = ref(false); const editing = ref<MonitoredUser | null>(null); const saving = ref(false); const action = ref('')
const filters = reactive({ page: 1, page_size: 15, search: '', status: 'all' }); const form = reactive({ username: '', interval: 300, useGlobal: true, include_replies: true, include_retweets: true })
const activeCount = computed(() => items.value.filter((item) => item.is_active).length)
async function load() { loading.value = true; try { const result = await monitoredUsersApi.list({ page: filters.page, page_size: filters.page_size, search: filters.search || undefined, is_active: filters.status === 'all' ? undefined : filters.status === 'active' }); items.value = result.items; total.value = result.total } catch (e) { message.error(getErrorMessage(e, '无法加载监听账号')) } finally { loading.value = false } }
function openEditor(item?: MonitoredUser) { editing.value = item || null; form.username = item?.username || ''; form.interval = item?.poll_interval_seconds || item?.effective_poll_interval_seconds || 300; form.useGlobal = item ? item.poll_interval_seconds == null : true; form.include_replies = item?.include_replies ?? true; form.include_retweets = item?.include_retweets ?? true; editorOpen.value = true }
async function save() { if ((!editing.value && !/^[A-Za-z0-9_]{1,15}$/.test(form.username.trim().replace(/^@/, ''))) || (!form.useGlobal && (form.interval < 15 || form.interval > 86400))) return message.warning('请填写有效的用户名与轮询间隔'); saving.value = true; try { const payload = { poll_interval_seconds: form.useGlobal ? null : Number(form.interval), include_replies: form.include_replies, include_retweets: form.include_retweets }; editing.value ? await monitoredUsersApi.update(editing.value.id, payload as UpdateMonitoredUserPayload) : await monitoredUsersApi.create({ ...payload, username: form.username.trim().replace(/^@/, '') } as CreateMonitoredUserPayload); editorOpen.value = false; message.success('监听配置已保存'); await load() } catch (e) { message.error(getErrorMessage(e, '保存失败')) } finally { saving.value = false } }
async function run(item: MonitoredUser, kind: 'toggle'|'poll'|'delete') { action.value = `${item.id}-${kind}`; try { if (kind === 'toggle') item.is_active ? await monitoredUsersApi.pause(item.id) : await monitoredUsersApi.resume(item.id); if (kind === 'poll') await monitoredUsersApi.pollNow(item.id); if (kind === 'delete') await monitoredUsersApi.remove(item.id); message.success(kind === 'delete' ? '监听账号已删除' : kind === 'poll' ? '轮询任务已提交' : item.is_active ? '监听已暂停' : '监听已恢复'); await load() } catch (e) { message.error(getErrorMessage(e, '操作失败')) } finally { action.value = '' } }
function remove(item: MonitoredUser) { Modal.confirm({ title: `删除 @${item.username}？`, content: '此操作会同时删除该账号已采集的内容与轮询历史。', okText: '确认删除', okType: 'danger', cancelText: '取消', onOk: () => run(item, 'delete') }) }
watch(() => [filters.search, filters.status], () => { filters.page = 1; void load() }); onMounted(load)
</script>

<template><div class="page-stack"><PageHeader eyebrow="MONITOR / 01" title="监听账号" description="管理 X 用户与独立轮询策略"><template #actions><a-button type="primary" @click="openEditor()"><PlusOutlined /> 添加账号</a-button></template></PageHeader><div class="metric-grid"><MetricCard label="当前页账号" :value="items.length" detail="分页结果" /><MetricCard label="运行中" :value="activeCount" detail="正在参与轮询" accent="sage" /><MetricCard label="已暂停" :value="items.length - activeCount" detail="可随时恢复" accent="slate" /><MetricCard label="总账号数" :value="total" detail="全部监听配置" accent="ochre" /></div><a-card :bordered="false"><div class="toolbar"><div class="toolbar__controls"><a-input v-model:value="filters.search" allow-clear placeholder="搜索用户名" style="width:220px" /><a-select v-model:value="filters.status" style="width:130px" :options="[{label:'全部状态',value:'all'},{label:'运行中',value:'active'},{label:'已暂停',value:'paused'}]" /><a-button @click="load"><ReloadOutlined /> 刷新</a-button></div><span class="toolbar__hint">共 {{ total }} 个账号</span></div><a-table :data-source="items" :loading="loading" :pagination="{ current: filters.page, pageSize: filters.page_size, total, showSizeChanger: false }" row-key="id" @change="(page: any) => { filters.page = page.current; load() }"><a-table-column title="账号" data-index="username"><template #default="{ record }"><strong>@{{ record.username }}</strong><div class="muted">{{ record.display_name || '未设置显示名称' }}</div></template></a-table-column><a-table-column title="状态"><template #default="{ record }"><StatusPill :value="record.status || record.is_active" /></template></a-table-column><a-table-column title="轮询频率"><template #default="{ record }">{{ formatInterval(record.effective_poll_interval_seconds) }}</template></a-table-column><a-table-column title="内容数" data-index="tweet_count" /><a-table-column title="下次轮询"><template #default="{ record }"><span class="muted">{{ formatDateTime(record.next_poll_at) }}</span></template></a-table-column><a-table-column title="操作" key="actions" width="210"><template #default="{ record }"><a-space><a-button type="link" size="small" @click="openEditor(record)"><EditOutlined /> 编辑</a-button><a-button type="link" size="small" :loading="action === `${record.id}-poll`" @click="run(record, 'poll')"><ThunderboltOutlined /> 立即轮询</a-button><a-dropdown><a-button type="text" size="small"><MoreOutlined /></a-button><template #overlay><a-menu><a-menu-item @click="run(record, 'toggle')">{{ record.is_active ? '暂停监听' : '恢复监听' }}</a-menu-item><a-menu-item danger @click="remove(record)">删除账号</a-menu-item></a-menu></template></a-dropdown></a-space></template></a-table-column></a-table></a-card><a-modal v-model:open="editorOpen" :title="editing ? `编辑 @${editing.username}` : '添加监听账号'" ok-text="保存" cancel-text="取消" :confirm-loading="saving" @ok="save"><a-form layout="vertical"><a-form-item v-if="!editing" label="X 用户名" required><a-input v-model:value="form.username" placeholder="例如 elonmusk" /></a-form-item><a-form-item label="轮询策略"><a-space direction="vertical" style="width:100%"><a-switch v-model:checked="form.useGlobal" checked-children="跟随系统默认" un-checked-children="独立间隔" /><a-input-number v-model:value="form.interval" :min="15" :max="86400" :disabled="form.useGlobal" addon-after="秒" style="width:100%" /></a-space></a-form-item><a-form-item label="采集范围"><a-checkbox v-model:checked="form.include_retweets">包含转推</a-checkbox><a-checkbox v-model:checked="form.include_replies">包含回复</a-checkbox></a-form-item></a-form></a-modal></div></template>
